def build_service_admin_pages():
    """在基础页面输出完成后，替换服务配置并增加通用展示配置。"""

    def e(value):
        return _service_escape(str(value), quote=True)

    def emit(name, title, body):
        path = 'admin/pc/' + name + '.html'
        PAGES[:] = [page for page in PAGES if page['path'] != path]
        output(path, title, SERVICE_ADMIN_CSS + body, role='admin', port='pc', active='services')

    def selected_field(label, name, choices, selected, help_text='', required=True):
        options = ''.join('<option value="'+e(value)+'"'+(' selected' if value == selected else '')+'>'+e(text)+'</option>' for value, text in choices)
        return '<div class="field"><label for="'+e(name)+'">'+label+(' <em>*</em>' if required else '')+'</label><select id="'+e(name)+'" name="'+e(name)+'"'+(' required' if required else '')+'>'+options+'</select>'+('<small>'+help_text+'</small>' if help_text else '')+'</div>'

    def section(number, title, description, body):
        return card('', '<div class="service-section-label"><span>'+str(number)+'</span><div><h2>'+title+'</h2><p>'+description+'</p></div></div>'+body)

    def progress(current=1):
        return '<ol class="service-admin-steps" aria-label="服务发布步骤">'+''.join('<li class="'+('current' if current == i else '')+'"'+(' aria-current="step"' if current == i else '')+'><b>'+str(i)+'</b>'+title+'</li>' for i, title in [(1, '编辑内容'), (2, '预览并确认'), (3, '发布完成')])+'</ol>'

    def display_progress(current=1):
        return '<ol class="service-admin-steps" aria-label="展示配置发布步骤">'+''.join('<li class="'+('current' if current == i else '')+'"'+(' aria-current="step"' if current == i else '')+'><b>'+str(i)+'</b>'+title+'</li>' for i, title in [(1, '编辑展示'), (2, '预览并确认'), (3, '发布完成')])+'</ol>'

    def sidebar():
        return '<aside class="service-admin-aside">'+card('配置后展示在哪里', '<div class="service-info-row">'+icon('fa-table-cells')+'<div><b>服务大厅</b><small>卡片名称、图标、简介、角标、分类及顺序。</small></div></div><div class="service-info-row">'+icon('fa-list-check')+'<div><b>服务指引</b><small>办理说明、步骤、对象、终端和办理按钮。</small></div></div><div class="service-info-row">'+icon('fa-laptop-mobile')+'<div><b>电脑端与手机端</b><small>发布后同步生效，按当前角色与终端展示。</small></div></div>')+card('发布规则', '<p>授权管理员预览确认后直接发布，修改时保留服务原有编号。</p><p>关闭“在服务大厅展示”只隐藏大厅卡片，已启用服务仍可通过关联入口查看指引。</p><p>停用后，服务大厅、关联问答中的办理入口与原服务指引同时停止对用户开放。</p><p>标准问答正文及引用依据继续在知识库管理中维护。</p>'+link('knowledge.html', '前往知识库管理', 'textlink', 'fa-arrow-up-right-from-square'))+'</aside>'

    # 服务大厅内容列表。
    list_actions = '<div class="actions">'+link('service-display.html', '通用展示配置', 'btn', 'fa-sliders')+link('service-edit.html?new=1', '新增服务', 'btn primary', 'fa-plus')+'</div>'
    intro = '<div class="service-admin-intro"><div><span class="service-intro-icon">'+icon('fa-table-cells-large')+'</span><div><h2>从卡片到指引，统一维护服务内容</h2><p>修改发布后同步到电脑端与手机端，师生可看到最新的办理说明与服务入口。</p></div></div>'+link('../../student/pc/services.html', '查看服务大厅', 'btn sm', 'fa-arrow-up-right-from-square')+'</div>'
    service_table = '<div class="table-wrap"><table class="service-admin-table"><thead><tr>'+''.join('<th>'+title+'</th>' for title in ['服务名称', '分类', '适用对象', '启用状态', '排序', '操作'])+'</tr></thead><tbody id="admin-service-content-list"></tbody></table></div>'
    body = heading('服务内容管理', '维护服务大厅卡片与完整办理指引，发布后前台同步展示', list_actions)+intro
    body += card('', '<div class="service-admin-list-bar"><div class="filters"><label class="sr-only" for="admin-service-search">搜索服务</label><input id="admin-service-search" type="search" placeholder="搜索服务名称、分类或适用对象" aria-label="搜索服务名称、分类或适用对象"></div><small>排序值越小，展示越靠前</small></div>'+service_table+'<p class="service-admin-list-foot">'+icon('fa-circle-info')+'启用状态控制服务是否对用户开放；“在大厅展示”可在编辑页单独设置。</p>')
    body += note('服务内容配置管理办事卡片、办理说明和服务地址；标准问答正文、知识来源及文件引用在知识库管理中维护。')
    emit('services', '服务内容管理', body)

    # 服务内容编辑，字段名称由共用交互脚本读取。
    icon_choices = [('fa-screwdriver-wrench', '维修工具 · 网上报修'), ('fa-comments', '对话气泡 · 服务监督'), ('fa-person-swimming', '游泳人物 · 游泳馆'), ('fa-file-lines', '文件 · 服务说明'), ('fa-bus', '巴士 · 班车查询'), ('fa-hotel', '宾馆 · 住宿服务'), ('fa-newspaper', '报纸 · 报刊订阅'), ('fa-magnifying-glass', '搜索 · 失物招领'), ('fa-bolt', '闪电 · 水电缴费'), ('fa-bullhorn', '公告 · 其他服务')]
    display_fields = '<div class="grid2">'+field('服务名称', '网上报修', name='name')+field('服务分类', '维修服务', name='category')+'</div>'
    display_fields += '<div class="grid2">'+selected_field('服务图标', 'icon', icon_choices, 'fa-screwdriver-wrench')+field('卡片角标', '服务指引', name='tag', required=False)+'</div>'
    display_fields += field('卡片简介', '宿舍和公共区域的日常零星维修。', 'textarea', 'summary')+'<p class="service-field-note">简介显示在服务大厅卡片中，建议用一到两句话说明服务用途。</p>'
    display_fields += field('问答触发说法', '报修、水龙头、灯管、门锁、空调不制冷', name='triggers', required=False)+'<p class="service-field-note">使用逗号分隔，便于将用户的提问关联到对应的办理入口。</p>'

    default_steps = [('准备报修信息', '确认校区、楼栋、房间，描述故障现象，可在原平台上传现场图片。'), ('进入网上报修平台', '在原平台创建报修单，并核对联系人及联系方式。'), ('查看受理和维修进度', '返回原平台查看处理记录；紧急故障请拨打后勤服务热线。')]
    step_rows = ''
    for i, (title, text) in enumerate(default_steps, 1):
        step_rows += '<div class="service-step-edit" data-service-step><div class="service-step-heading"><b>步骤 '+str(i)+'</b><button class="service-step-remove" type="button" data-remove-step aria-label="删除步骤 '+str(i)+'">'+icon('fa-trash-can')+'删除</button></div><div class="field"><label for="step-title-'+str(i)+'">步骤名称 <em>*</em></label><input id="step-title-'+str(i)+'" data-step-title value="'+e(title)+'" required></div><div class="field"><label for="step-text-'+str(i)+'">操作说明 <em>*</em></label><textarea id="step-text-'+str(i)+'" data-step-text rows="2" required>'+e(text)+'</textarea></div></div>'
    guide_fields = field('详细办理说明', '可报修家具、门锁、空调，以及建筑物公共部分的泥、木、水、电。也可以拨打后勤服务热线 0731-88836000，全天有人值班。报修单在原系统里填写，助手不保存单据。', 'textarea', 'detail')+'<hr class="service-form-divider"><div class="field"><label>办理步骤</label><small>按用户实际办理顺序填写，可增加或删除步骤。</small></div><div id="service-steps-editor">'+step_rows+'</div><button id="add-service-step" class="btn sm" type="button">'+icon('fa-plus')+'添加办理步骤</button>'
    channel_fields = '<div class="grid2">'+field('办理渠道', '原业务系统', name='channel')+selected_field('终端支持', 'terminal', [(x, x) for x in ['电脑与手机分别配置', '仅电脑', '仅手机', '无地址，仅文字说明']], '电脑与手机分别配置')+'</div>'
    channel_fields += field('电脑正式地址', 'http://zhhq.csu.edu.cn/stu/repairHome.html', 'url', 'pc', required=False)+field('手机正式地址', 'https://zhhq.csu.edu.cn/wx/#/repairHome?app_id=5', 'url', 'mobile', required=False)+'<p class="service-field-note">仅填写所选终端需要的正式地址；无地址服务保留文字指引和咨询方式。</p>'
    channel_fields += '<div class="grid2">'+field('办理按钮文案', '前往办理', name='buttonText')+field('手机办理按钮文案', '手机扫码办理', name='qrButtonText')+'</div>'
    channel_fields += field('无当前终端地址时的提示', '当前终端暂未提供在线办理地址，请参考办理说明或联系后勤服务热线。', 'textarea', 'fallbackText')+field('办理提示', '服务由原业务系统提供。报修单在原平台提交，处理进度和结果也在原平台查看。', 'textarea', 'notice', required=False)
    scope_fields = '<div class="grid2">'+selected_field('适用对象', 'who', [(x, x) for x in ['学生、教职工', '学生', '教职工', '全部用户（说明）']], '学生、教职工')+selected_field('是否启用', 'enabled', [('是', '是 · 对适用对象开放'), ('否', '否 · 暂停服务展示与访问')], '是')+'</div>'
    scope_fields += '<div class="grid2">'+selected_field('在服务大厅展示', 'showInHall', [('是', '是 · 展示服务卡片'), ('否', '否 · 仅作为关联办理指引')], '是')+field('展示排序', '10', 'number', 'sort')+'</div><p class="service-field-note">游客可浏览已启用的功能卡片，点击使用时再登录；登录后按学生、教职工适用范围展示指引和办理入口。公开知识可直接咨询，个人数据与正式办理仍遵循原系统认证和授权规则。</p>'
    form = '<form id="service-content-form" class="service-admin-form" action="service-preview.html" method="get"><input type="hidden" name="id" value="repair"><div id="service-form-error" class="service-content-error" role="alert" aria-live="polite"></div><div class="service-admin-layout"><div>'+section(1, '卡片展示', '设置服务大厅中的第一印象与问答关联', display_fields)+section(2, '办理指引', '将办理说明拆成师生容易理解的步骤', guide_fields)+section(3, '渠道和终端', '分别配置电脑与手机入口及办理提示', channel_fields)+section(4, '发布范围', '控制哪些用户可以看到，以及在哪里展示', scope_fields)+'</div>'+sidebar()+'</div><div class="service-admin-actions"><p>'+icon('fa-arrows-rotate')+'预览确认并发布后，服务大厅与指引页同步更新。</p><div class="actions">'+link('services.html', '取消')+'<button class="btn primary" type="submit">'+icon('fa-eye')+'预览并发布</button></div></div></form>'
    emit('service-edit', '配置服务内容', heading('配置服务内容', '完整维护服务卡片、办理步骤、服务地址与可见范围', link('services.html', '返回列表', 'btn', 'fa-arrow-left'))+progress()+form)

    # 双端预览与最终发布确认。
    def guide_sample(mobile=False):
        main = '<div class="detail-banner"><div class="service-icon">'+icon('fa-screwdriver-wrench')+'</div><div><h1>网上报修</h1><p>宿舍和公共区域的日常零星维修。</p></div></div><p style="font-size:13px">可报修家具、门锁、空调，以及建筑物公共部分的泥、木、水、电。紧急故障可拨打后勤服务热线 0731-88836000。</p><hr class="service-form-divider"><h2>办理步骤</h2><div class="steps">'+''.join('<div class="step"><span>'+str(i)+'</span><div><h3>'+e(title)+'</h3><p>'+e(text)+'</p></div></div>' for i, (title, text) in enumerate(default_steps, 1))+'</div>'
        info = '<dl class="summary-list"><div><dt>适用对象</dt><dd>学生、教职工</dd></div><div><dt>办理渠道</dt><dd>原业务系统</dd></div><div><dt>终端支持</dt><dd>电脑与手机分别配置</dd></div></dl><div class="btn primary" style="margin-top:20px">'+icon('fa-arrow-up-right-from-square')+'前往办理</div>'
        return '<div class="service-preview-stage'+(' service-mobile-stage' if mobile else '')+'"><div class="eyebrow">中南大学 · 智慧后勤</div><h1>服务指引</h1><p>办事之前，先把流程看清楚</p>'+card('', main)+card('办理信息', info)+'</div>'

    preview = heading('预览服务内容', '发布前核对卡片、办理说明、步骤和两端入口', '<a id="service-back-edit" class="btn" href="service-edit.html?service=repair">'+icon('fa-arrow-left')+'返回修改</a>')+progress(2)
